-- Create "identities" table
CREATE TABLE "identities" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "provider" character varying NOT NULL,
  "provider_user_id" character varying NOT NULL,
  "created_at" timestamptz NOT NULL,
  "user_identities" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "identities_users_identities" FOREIGN KEY ("user_identities") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);
-- Create index "identity_provider_provider_user_id" to table: "identities"
CREATE UNIQUE INDEX "identity_provider_provider_user_id" ON "identities" ("provider", "provider_user_id");
-- Create "sessions" table
CREATE TABLE "sessions" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "token_hash" character varying NOT NULL,
  "expires_at" timestamptz NOT NULL,
  "revoked" boolean NOT NULL DEFAULT false,
  "device" character varying NULL,
  "created_at" timestamptz NOT NULL,
  "user_sessions" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "sessions_users_sessions" FOREIGN KEY ("user_sessions") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);
-- Create index "sessions_token_hash_key" to table: "sessions"
CREATE UNIQUE INDEX "sessions_token_hash_key" ON "sessions" ("token_hash");
